#!/usr/bin/env bash
# ============================================================================
# patch.sh - Day 3 "Provider Routing & Execution Stack" upgrade
#
# Adds a real, first-class POST /v1/execute endpoint (the provider-neutral
# execution contract Stack 5 requires) alongside the existing POST /v1/chat
# endpoint, without aliasing one to the other. See README.md (after patching)
# for the full /v1/execute request/response contract.
#
# Usage:
#   chmod +x patch.sh
#   ./patch.sh
#
# Optional: set DAY3_URL to point at a running instance for live
# verification (defaults to http://localhost:4405).
#
#   DAY3_URL=http://localhost:4405 ./patch.sh
#
# Safe to run more than once: every edit is idempotent and verified.
# ============================================================================
set -u
set -o pipefail

RED='\033[0;31m'; GREEN='\033[0;32m'; YELLOW='\033[1;33m'; BLUE='\033[0;34m'; NC='\033[0m'
PASS_COUNT=0
FAIL_COUNT=0

pass() { PASS_COUNT=$((PASS_COUNT+1)); echo -e "${GREEN}[PASS]${NC} $1"; }
fail() { FAIL_COUNT=$((FAIL_COUNT+1)); echo -e "${RED}[FAIL]${NC} $1"; }
warn() { echo -e "${YELLOW}[WARN]${NC} $1"; }
info() { echo -e "${BLUE}[INFO]${NC} $1"; }
section() { echo; echo "== $1 =="; }

# ---------------------------------------------------------------------------
# 1. Locate and verify the repository root
# ---------------------------------------------------------------------------
section "1. LOCATING REPOSITORY"

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT=""
for candidate in "$SCRIPT_DIR" "$(pwd)"; do
  if [ -f "$candidate/src/server.js" ] && [ -f "$candidate/package.json" ]; then
    if grep -q '"name": "ai-gateway-3-of-10-provider-routing"' "$candidate/package.json" 2>/dev/null; then
      REPO_ROOT="$candidate"
      break
    fi
  fi
done

if [ -z "$REPO_ROOT" ]; then
  fail "Could not locate the Day 3 repository. Expected src/server.js and a package.json"
  fail "with name \"ai-gateway-3-of-10-provider-routing\" in $SCRIPT_DIR or \$(pwd)."
  fail "Run this script from inside the repository, or place it in the repository root."
  exit 1
fi
info "Repository root: $REPO_ROOT"

REQUIRED_FILES=(
  src/server.js src/routes/meta.js src/routes/chat.js src/lib/config.js
  src/lib/router.js src/lib/logger.js src/lib/metrics.js src/lib/db.js
  src/lib/redisClient.js src/providers/registry.js src/providers/groq.js
  package.json docker-compose.yml .env.example README.md
)
MISSING=0
for f in "${REQUIRED_FILES[@]}"; do
  if [ ! -f "$REPO_ROOT/$f" ]; then
    fail "Expected source file missing: $f"
    MISSING=1
  fi
done
if [ "$MISSING" -ne 0 ]; then
  fail "Repository does not match the expected Day 3 structure. Aborting without changes."
  exit 1
fi
pass "Repository structure matches the expected Day 3 layout"

command -v python3 >/dev/null 2>&1 || { fail "python3 is required to apply deterministic source patches"; exit 1; }
command -v node >/dev/null 2>&1 || { fail "node is required for syntax checks and tests"; exit 1; }
pass "python3 and node are available"

# ---------------------------------------------------------------------------
# 2. Backups
# ---------------------------------------------------------------------------
section "2. BACKUPS"

TS="$(date +%Y%m%d%H%M%S)"
BACKUP_DIR="$REPO_ROOT/.patch-backups/$TS"
mkdir -p "$BACKUP_DIR"
info "Backups (originals of any file this patch touches) will be written to:"
info "  $BACKUP_DIR"

# ---------------------------------------------------------------------------
# 3. Apply deterministic, idempotent source edits + create new files
# ---------------------------------------------------------------------------
section "3. APPLYING PATCH"

WORKDIR="$(mktemp -d)"
trap 'rm -rf "$WORKDIR"' EXIT

PAYLOAD_FILE="$WORKDIR/payload.b64"
PATCHER_FILE="$WORKDIR/apply_patch.py"

