cat > "$PATCHER_FILE" << 'PATCH_PY_EOF'
#!/usr/bin/env python3
"""Deterministic, idempotent patch applier for Day 3 (Stack 3) /v1/execute upgrade.

Usage: apply_patch.py <repo_root> <backup_dir> <payload_b64_path>

For each entry in "edits": if the target file already contains the new
content, it is skipped (already applied). If it contains the exact expected
old content, it is backed up and replaced, then re-verified. If neither is
found, the patch fails loudly rather than guessing.

For each entry in "new_files": if the target already exists and contains the
marker, it is skipped. Otherwise it is (optionally backed up and) written.
"""
import base64
import json
import os
import shutil
import sys


def read(path):
    with open(path, 'r', encoding='utf-8') as f:
        return f.read()


def write(path, content):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, 'w', encoding='utf-8') as f:
        f.write(content)


def backup(repo_root, backup_dir, path):
    rel = os.path.relpath(path, repo_root)
    dest = os.path.join(backup_dir, rel)
    os.makedirs(os.path.dirname(dest), exist_ok=True)
    shutil.copy2(path, dest)


def main():
    if len(sys.argv) != 4:
        print("[FAIL] apply_patch.py: expected <repo_root> <backup_dir> <payload_b64_path>")
        return 1

    repo_root, backup_dir, payload_path = sys.argv[1], sys.argv[2], sys.argv[3]

    payload_b64 = read(payload_path).strip()
    payload = json.loads(base64.b64decode(payload_b64).decode('utf-8'))

    failed = []
    applied = []
    skipped = []

    for entry in payload.get('edits', []):
        relpath = entry['path']
        desc = entry.get('desc', relpath)
        path = os.path.join(repo_root, relpath)
        old = base64.b64decode(entry['old_b64']).decode('utf-8')
        new = base64.b64decode(entry['new_b64']).decode('utf-8')

        if not os.path.exists(path):
            failed.append(f"{relpath}: file not found ({desc})")
            continue

        content = read(path)

        if content == new:
            skipped.append(f"{relpath}: already applied ({desc})")
            continue

        if content != old:
            failed.append(
                f"{relpath}: expected source pattern not found - file has diverged from the "
                f"inspected repository state ({desc}). Refusing to guess; no changes made to this file."
            )
            continue

        backup(repo_root, backup_dir, path)
        write(path, new)

        verify = read(path)
        if verify != new:
            failed.append(f"{relpath}: verification failed after writing ({desc})")
            continue

        applied.append(f"{relpath}: {desc}")

    for entry in payload.get('new_files', []):
        relpath = entry['path']
        marker = entry['marker']
        path = os.path.join(repo_root, relpath)
        content = base64.b64decode(entry['content_b64']).decode('utf-8')

        if os.path.exists(path):
            existing = read(path)
            if marker in existing:
                skipped.append(f"{relpath}: already present (idempotent)")
                continue
            # File exists but wasn't created by this patch - back it up before overwriting,
            # rather than silently discarding whatever is there.
            backup(repo_root, backup_dir, path)

        write(path, content)

        verify = read(path)
        if marker not in verify:
            failed.append(f"{relpath}: verification failed after writing new file")
            continue

        applied.append(f"{relpath}: created")

    for a in applied:
        print(f"[APPLIED] {a}")
    for s in skipped:
        print(f"[SKIP] {s}")
    for f in failed:
        print(f"[FAIL] {f}")

    if failed:
        return 1
    return 0


if __name__ == '__main__':
    sys.exit(main())
PATCH_PY_EOF

python3 "$PATCHER_FILE" "$REPO_ROOT" "$BACKUP_DIR" "$PAYLOAD_FILE"
PY_STATUS=$?

if [ "$PY_STATUS" -ne 0 ]; then
  fail "Deterministic source patch step failed (see [FAIL] lines above)."
  fail "No further steps will run. Any files already backed up are under: $BACKUP_DIR"
  exit 1
fi
pass "Source edits applied (or already present) to existing files"
pass "New files present: src/lib/executionService.js, src/routes/execute.js, tests/run-tests.js, tests/e2e-execute.sh"
chmod +x "$REPO_ROOT/tests/e2e-execute.sh" 2>/dev/null || true

# ---------------------------------------------------------------------------
# 4. Syntax checks
# ---------------------------------------------------------------------------
section "4. SYNTAX CHECKS"

SYNTAX_FAIL=0
while IFS= read -r -d '' f; do
  ERR_OUT="$(node --check "$f" 2>&1)"
  if [ $? -ne 0 ]; then
    fail "Syntax error in $f: $ERR_OUT"
    SYNTAX_FAIL=1
  fi
done < <(find "$REPO_ROOT/src" -name "*.js" -print0)

ERR_OUT="$(node --check "$REPO_ROOT/tests/run-tests.js" 2>&1)"
if [ $? -ne 0 ]; then
  fail "Syntax error in tests/run-tests.js: $ERR_OUT"
  SYNTAX_FAIL=1
fi

bash -n "$REPO_ROOT/tests/e2e-execute.sh" || { fail "Syntax error in tests/e2e-execute.sh"; SYNTAX_FAIL=1; }

if [ "$SYNTAX_FAIL" -ne 0 ]; then
  fail "Syntax check failed; aborting before touching dependencies or runtime."
  exit 1
fi
pass "All patched/new JS and shell files pass syntax checks (node --check / bash -n)"

# ---------------------------------------------------------------------------
# 5. Dependencies (best effort - required packages were already in package.json)
# ---------------------------------------------------------------------------
section "5. DEPENDENCIES"

if [ -d "$REPO_ROOT/node_modules" ]; then
  info "node_modules already present, skipping npm install"
else
  ( cd "$REPO_ROOT" && npm install --no-audit --no-fund --silent )
  if [ $? -eq 0 ]; then
    pass "npm install completed"
  else
    warn "npm install failed or was skipped (no network access?). This patch adds no new"
    warn "dependencies beyond what package.json already declared, so this is non-fatal."
  fi
fi

# ---------------------------------------------------------------------------
# 6. Live verification (best effort) + test suite
# ---------------------------------------------------------------------------
section "6. LIVE VERIFICATION"

DAY3_URL="${DAY3_URL:-http://localhost:4405}"
info "Checking for a running instance at $DAY3_URL ..."

if curl -sf -m 5 "$DAY3_URL/health" >/dev/null 2>&1; then
  pass "Live instance reachable at $DAY3_URL"

  echo "---- GET /health ----";        curl -s -m 5 "$DAY3_URL/health"; echo
  echo "---- GET /ready ----";         curl -s -m 5 "$DAY3_URL/ready"; echo
  echo "---- GET /dependencies ----";  curl -s -m 5 "$DAY3_URL/dependencies"; echo
  echo "---- GET /providers ----";     curl -s -m 5 "$DAY3_URL/providers"; echo
  echo "---- GET /help ----";          curl -s -m 5 "$DAY3_URL/help"; echo
  echo "---- GET /metrics (first line) ----"; curl -s -m 5 "$DAY3_URL/metrics" | head -1; echo

  EXECUTE_STATUS="$(curl -s -m 5 -o /dev/null -w '%{http_code}' -X POST "$DAY3_URL/v1/execute" \
    -H 'Content-Type: application/json' \
    -d '{"provider":"nonexistent-provider","messages":[{"role":"user","content":"ping"}]}')"
  if [ "$EXECUTE_STATUS" != "404" ]; then
    pass "POST /v1/execute route exists (status $EXECUTE_STATUS, not the old catch-all 404)"
  else
    fail "POST /v1/execute still returns 404 - route not mounted. Restart the service to pick up the patch."
  fi

  info "Running full test suite: node tests/run-tests.js"
  DAY3_URL="$DAY3_URL" node "$REPO_ROOT/tests/run-tests.js"
  RUN_TESTS_STATUS=$?
  if [ "$RUN_TESTS_STATUS" -eq 0 ]; then
    pass "tests/run-tests.js completed with no failures"
  else
    fail "tests/run-tests.js reported failures (see output above)"
  fi

  info "Running real end-to-end execution test: tests/e2e-execute.sh"
  DAY3_URL="$DAY3_URL" bash "$REPO_ROOT/tests/e2e-execute.sh"
  E2E_STATUS=$?
  if [ "$E2E_STATUS" -eq 0 ]; then
    pass "tests/e2e-execute.sh completed (real execution passed, or provider credentials are"
    pass "legitimately not configured on this deployment - see PROVIDER CONFIGURATION MISSING above)"
  else
    fail "tests/e2e-execute.sh reported a real provider execution failure (PROVIDER EXECUTION FAILED)"
  fi
else
  warn "No live instance reachable at $DAY3_URL - skipping live verification and test suite."
  warn "This does NOT fail the patch: the code changes above are already syntax-checked."
  warn "After starting the stack, verify manually with:"
  warn "  DAY3_URL=http://localhost:4405 node tests/run-tests.js"
  warn "  DAY3_URL=http://localhost:4405 bash tests/e2e-execute.sh"
fi

# ---------------------------------------------------------------------------
# 7. Summary
# ---------------------------------------------------------------------------
section "7. SUMMARY"

echo
echo "============================================================"
echo " PATCH SUMMARY"
echo "============================================================"
echo " PASS: $PASS_COUNT"
echo " FAIL: $FAIL_COUNT"
echo " Backups: $BACKUP_DIR"
echo "============================================================"

if [ "$FAIL_COUNT" -gt 0 ]; then
  echo "Patch completed WITH FAILURES. Review [FAIL] lines above before deploying."
  exit 1
fi

echo "Patch applied successfully."
echo
echo "POST /v1/execute is now a real, first-class Stack 3 execution endpoint,"
echo "sharing routing/execution/metrics/persistence with POST /v1/chat via"
echo "src/lib/executionService.js. See README.md for the full contract."
echo
echo "Next steps:"
echo "  1. Restart/rebuild the Stack 3 container so it picks up these changes"
echo "     (e.g. docker compose up -d --build)."
echo "  2. Re-run the Stack 5 integration diagnostic (stack5-integration-test.sh)."
exit 0
